import{z as h,x as A,o as E,c as B,q as l,j as s,D as e,d as i,s as o,S as r,b as t}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"隐函数定理","description":"","frontmatter":{"title":"隐函数定理","date":"2026-09-10T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/implicit-function.md","filePath":"econ/implicit-function.md","lastUpdated":1791063341000}'),x={name:"econ/implicit-function.md"};function p(D,a,F,d,m,_){const n=A("Mermaid");return E(),B("div",null,[a[2]||(a[2]=l('<h1 id="隐函数定理" tabindex="-1">隐函数定理 <a class="header-anchor" href="#隐函数定理" aria-label="Permalink to &quot;隐函数定理&quot;">​</a></h1><div class="epigraph"><p>一阶条件是 $n$ 个方程；$x$ 对参数可解，当且仅当那组方程对 $x$ 的 Jacobian 可逆。</p><footer>—— 据 Rudin, Principles of Mathematical Analysis, 第 9 章；Mas-Colell, Whinston and Green 数学附录整理</footer></div><p>上一课<a href="/econ/envelope-theorem">包络定理</a>把 \\(V&#39;(\\theta)\\) 写成直接偏导，故意丢掉 \\(Dx^*\\)。比较静态若问「价格涨，买多还是买少」，丢掉的那一项必须回来。缺口是：由 \\(F(x,\\theta)=0\\)（通常是 FONC 或 KKT 的平稳方程）局部解出 \\(x(\\theta)\\)，并给出 \\(Dx\\)。本课只提供这条微积分许可，不把经济学符号推完——那是下一课比较静态。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(F:\\mathbb{R}^n\\times\\mathbb{R}^k\\to\\mathbb{R}^n\\) 为 \\(C^1\\)，\\(F(x_0,\\theta_0)=0\\)，且 \\(D_x F(x_0,\\theta_0)\\) 可逆。则存在 \\((x_0,\\theta_0)\\) 的邻域，使 \\(x=x(\\theta)\\) 为 \\(C^1\\)，且 \\(D_\\theta x=-(D_x F)^{-1}D_\\theta F\\)。 经济学里 \\(F=\\nabla_x\\mathcal{L}\\) 或无约束的 \\(\\nabla f\\)。\\(D_x F\\) 就是 Hessian（或加了约束后的加边 Hessian）。可逆 = 非退化驻点 = 局部唯一的 \\(x(\\theta)\\)。</p><p>加边 Hessian 非奇异，是支出最小化、效用最大化内部解比较静态的标准假设。它失败时：完全替代的整段需求、有效约束集合跳变、多重最优。那些情形没有单值可微的 \\(x(\\theta)\\)，包络仍可能用次梯度说话，但本课的公式不适用。</p><p><span class="marginnote">「\\(D_xF\\) 可逆」翻译成人话：这组方程恰好能唯一解出 \\(x\\)。一元情形它就是一个导数、不为零即可；数字实例——\\(F(x,\\theta)=x^2-\\theta\\)，\\(D_xF=2x\\) 在 \\(x_0=0\\) 处等于零，定理失效，果然 \\(\\theta\\gt 0\\) 时冒出 \\(\\pm\\sqrt\\theta\\) 两个解。可逆性正是把这种分叉排除掉的条件。</span></p><h3 id="隐函数不是「把-解出来」" tabindex="-1">隐函数不是「把 \\(x\\) 解出来」 <a class="header-anchor" href="#隐函数不是「把-解出来」" aria-label="Permalink to &quot;隐函数不是「把 $x$ 解出来」&quot;">​</a></h3><p>定理不保证闭式。\\(u\\) 的 FONC 很少能把 \\(x\\) 写成初等函数；定理只说局部存在一张 \\(C^1\\) 的图，并且告诉你斜率。比较静态要的是斜率的符号，不是公式。把隐函数理解成「先解出 \\(x=g(\\theta)\\) 再代入」会在 CES 以外的问题里走死。</p><p><span class="marginnote">方程个数必须等于内生变量个数。多出来的乘子要么被约束消掉，要么进入扩大的 \\(F\\)。KKT 在角点附近有效集不变时，对有效变量用隐函数。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把参数分成你关心的 \\(\\theta\\) 与其余。计算 \\(D_x F\\) 与 \\(D_\\theta F\\)，解线性方程 \\(D_x F\\cdot x_\\theta=-D_\\theta F\\)。符号由 \\((D_x F)^{-1}\\) 的负定性或加边矩阵的符号模式给出——下一课把这些模式翻译成替代、收入效应。本课停在线性代数：可逆就有局部函数。</p><p>高维时不要对每个分量分别「当一元隐函数」除非交叉偏导为零。同时动的 \\(x_i\\) 必须一起求。这也是为什么两商品可以画图消元、多商品必须上矩阵。</p>',13)),(E(),s(r,null,{default:e(()=>[o(n,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20FONC%5B%22%E4%B8%80%E9%98%B6%E6%9D%A1%E4%BB%B6%20F(x%2Ctheta)%3D0%22%5D%20--%3E%20J%5B%22Dx%20F%20%E5%8F%AF%E9%80%86%22%5D%0A%20%20J%20--%3E%20X%5B%22%E5%B1%80%E9%83%A8%20x%20%E7%AD%89%E4%BA%8E%20x(theta)%22%5D%0A%20%20X%20--%3E%20DX%5B%22Dx%20%E7%AD%89%E4%BA%8E%E8%B4%9F%20(Dx%20F)%20%E9%80%86%E4%B9%98%20D%20theta%20F%22%5D%0A%20%20DX%20--%3E%20CS%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E7%BB%99%E6%96%9C%E7%8E%87%E8%B4%B4%E7%BB%8F%E6%B5%8E%E7%AC%A6%E5%8F%B7%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[i("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"\\(F=0\\) 定义一张曲面。若曲面在 \\(x\\) 方向的切空间投影满秩，就能把曲面写成 \\(x\\) 对 \\(\\theta\\) 的图。满秩失败是折叠：同一 \\(\\theta\\) 对应多个 \\(x\\)，或突然消失——多重均衡、弯折的最优对应。Brouwer/Kakutani 仍可保证存在，但不给可微分支；那是后课不动点的语言，与本课互补：隐函数管局部光滑枝，不动点管全局存在。",-1)),a[5]||(a[5]=t("p",null,[t("span",{class:"marginnote"},"折叠可以想象成把一张纸沿对角线对折：折痕上方同一根竖线要么穿过纸面两次（同一 \\(\\theta\\) 两个 \\(x\\)），要么擦不到纸边（解消失）。多重均衡和需求的突然跳跃，在几何上就是这种折痕的经济学化身。")],-1)),(E(),s(r,null,{default:e(()=>[o(n,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E6%96%B9%E7%A8%8B%20F(x%2Ctheta)%3D0%20%E5%AE%9A%E4%B9%89%E4%B8%80%E5%BC%A0%E6%9B%B2%E9%9D%A2%22%5D%20--%3E%20Q%7B%22Dx%20F%20%E5%9C%A8%E8%AF%A5%E7%82%B9%E5%8F%AF%E9%80%86%3F%22%7D%0A%20%20Q%20--%3E%7C%22%E5%8F%AF%E9%80%86%3A%20%E5%88%87%E5%90%91%E6%8A%95%E5%BD%B1%E6%BB%A1%E7%A7%A9%22%7C%20G%5B%22%E6%9B%B2%E9%9D%A2%E5%B1%80%E9%83%A8%E5%8F%AF%E5%86%99%E6%88%90%20x%20%E5%AF%B9%20theta%20%E7%9A%84%E5%9B%BE%22%5D%0A%20%20G%20--%3E%20C1%5B%22%E5%8D%95%E5%80%BC%E5%8F%AF%E5%BE%AE%E7%9A%84%20x(theta)%22%5D%0A%20%20C1%20--%3E%20CS%5B%22%E6%AF%94%E8%BE%83%E9%9D%99%E6%80%81%E5%8F%AF%E7%94%A8%E6%96%9C%E7%8E%87%E5%85%AC%E5%BC%8F%22%5D%0A%20%20Q%20--%3E%7C%22%E5%A5%87%E5%BC%82%3A%20%E6%8A%95%E5%BD%B1%E4%B8%8D%E6%BB%A1%E7%A7%A9%22%7C%20FOLD%5B%22%E6%8A%98%E5%8F%A0%E7%82%B9%22%5D%0A%20%20FOLD%20--%3E%20C2%5B%22%E5%90%8C%E4%B8%80%20theta%20%E5%A4%9A%E4%B8%AA%20x%20%E6%88%96%E8%A7%A3%E6%B6%88%E5%A4%B1%22%5D%0A%20%20C2%20--%3E%20C3%5B%22%E5%A4%9A%E9%87%8D%E5%9D%87%E8%A1%A1%E6%88%96%E9%9C%80%E6%B1%82%E8%B7%B3%E8%B7%83%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=l('<p>\\(C^1\\) 的 \\(F\\) 给出 \\(C^1\\) 的 \\(x(\\theta)\\)；\\(C^2\\) 给出 \\(C^2\\)。后课斯勒茨基要用 \\(x\\) 对 \\((p,w)\\) 可微，默认加边 Hessian 在最优点可逆。二阶充分条件（切空间负定）往往蕴含这块可逆，但要把约束的加边写对。</p><p><span class="marginnote">离散选择没有内部 Jacobian。包络仍在（Milgrom–Segal），隐函数不在。不要对 0-1 决策套本课公式。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不在本课证明隐函数（Rudin 用压缩或平均微分）。不把反函数定理单独铺成一课：反函数是 \\(k=n\\) 且 \\(F(x,\\theta)=x-\\theta\\) 一类的特例。也不进入流形上的横截性讲义。下一课把 \\(Dx\\) 的符号读成替代与收入。</p><p><span class="marginnote">初学者容易把多重均衡当成定理「出了 bug」，实际上 \\(D_xF\\) 奇异的点恰好是分岔的候选地址——定理的失败区就是多重均衡可能住着的区域；绕开失败区用本课的斜率公式，走进失败区才需要动点与集值工具。</span></p><p>后课默认：非退化内部解存在局部 \\(C^1\\) 的 \\(x(\\theta)\\)，导数由 \\(-(D_x F)^{-1}D_\\theta F\\) 给出。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(F(x,\\theta)=0\\) 且 \\(D_x F\\) 可逆 \\(\\Rightarrow\\) 局部 \\(x(\\theta)\\) 为 \\(C^1\\)。</li><li>斜率公式是线性方程，不必有闭式解。</li><li>加边 Hessian 奇异时需求可以集值或跳跃，本课公式停用。</li><li>隐函数管光滑枝；存在性另由不动点管。</li><li>下一课：<a href="/econ/comparative-statics">比较静态</a>。</li><li>出处：Rudin, <em>Principles of Mathematical Analysis</em>；MWG 数学附录。</li></ul>',8))])}const u=h(x,[["render",p]]);export{C as __pageData,u as default};
